return(function(...)local c={}local i=0 local a=40 local function D(D,N,v)local V=c[D]local g=N*v if i+g>a then return false,"too heavy: "..D end if V==nil then V={weight=N;quantity=0}c[D]=V end V.quantity=V.quantity+v i=i+g return true end local function N(a,D)local N=c[a]if N==nil or N.quantity<D then return false,"not enough "..a end N.quantity=N.quantity-D i=i-N.weight*D if N.quantity==0 then c[a]=nil end return true end local function v()local a={}for c in pairs(c)do a[#a+1]=c end table.sort(a)for i,a in ipairs(a)do local D=c[a]print(a..(" x"..(D.quantity..(" ("..(D.weight*D.quantity.."kg)")))))end print("total weight: "..i)end print(D("rope",3,2))print(D("lantern",5,1))print(D("anvil",30,2))print(N("rope",1))print(N("sword",1))v()end)(...)